Here is the commit message:
network: fix assertion when link get carrier

This fixes a bug introduced by bd08ce56156751d58584a44e766ef61340cdae2d.
When link is in LINK_STATE_INITIALIZED, `Link::network` may not be
set yet.

Fixes #12452.

Here is the root cause:
network` is set, leading to potential assertion failures when the link's carrier is detected. The original conditions allowed for actions to be taken in states that should not have been valid, resulting in the assertion failure.

Here is the patch:

 int link_ipv6ll_gained(Link *link, const struct in6_addr *address) {
         int r;

         assert(link);

         log_link_info(link, "Gained IPv6LL");

         link->ipv6ll_address = *address;
         link_check_ready(link);

-        if (!IN_SET(link->state, LINK_STATE_PENDING, LINK_STATE_UNMANAGED, LINK_STATE_FAILED)) {
+        if (IN_SET(link->state, LINK_STATE_CONFIGURING, LINK_STATE_CONFIGURED)) {
                 r = link_acquire_ipv6_conf(link);
                 if (r < 0) {
                         link_enter_failed(link);
                         return r;
                 }
         }

         return 0;
 }

 static int link_carrier_gained(Link *link) {
         int r;

         assert(link);

-        if (!IN_SET(link->state, LINK_STATE_PENDING, LINK_STATE_UNMANAGED, LINK_STATE_FAILED)) {
+        if (IN_SET(link->state, LINK_STATE_CONFIGURING, LINK_STATE_CONFIGURED)) {
                 r = link_acquire_conf(link);
                 if (r < 0) {
                         link_enter_failed(link);
                         return r;
                 }

                 r = link_request_set_addresses(link);
                 if (r < 0)
                         return r;
         }

         r = link_handle_bound_by_list(link);
         if (r < 0)
                 return r;

         return 0;
 }



